import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
/** Actual ordinary poem resistance [2,3]; C priority for S01/02/05, B priority for S03/04. */
export function makeR6RollScenario(players:{id:string;name:string}[],thirdParty=false,canceledChild=false):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'侍大将のシン');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[b]!.permanent!.spirit=(s.players[b]!.permanent!.spirit??0)+12-gameStats(s,b).spirit;
 const poem=takeCard(s,a,'a2-p17-r1c1'),god=takeCard(s,canceledChild?c:thirdParty?d:b,'a2-p02-r1c3'),fate=takeCard(s,canceledChild?d:c,'a2-p02-r2c3');trimHand(s,a,poem);trimHand(s,b,...(thirdParty?[]:[god]));trimHand(s,c,canceledChild?god:fate);trimHand(s,d,...(canceledChild?[fate]:thirdParty?[god]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:[2,3]},r=transition(s,input,e);if(!r.ok)throw Error(`S01_05_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('S01_05_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('S01_05_FIXTURE_CARDS');}
 readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'ATTACK',cardInstanceId:poem,targetIds:[b],dedicated:false});for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='after-roll'&&w.participants[w.cursor]===(thirdParty?c:b))return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('S01_05_FIXTURE_WINDOW');
}
